.kind-recipe,
.kind-dashboard {
  --kind-recipe-1: #396b57;
  --kind-recipe-2: #8573b1;
  --kind-recipe-grid: #e5e9e2;
  color: #253d32;
  font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif);
}
.kind-recipe {
  min-width: 0;
  border: 1px solid #e2e7dc;
  border-radius: 1.25rem;
  background: #fffef9;
  box-shadow: 0 4px 18px #253d3205;
}
.kind-recipe-area {
  --kind-recipe-1: #376b99;
  --kind-recipe-2: #ac7353;
}
.kind-recipe-bar {
  --kind-recipe-1: #78629c;
  --kind-recipe-2: #4a827d;
}
.kind-recipe-eyebrow {
  margin: 0 0 0.65rem;
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: #667568;
}
.kind-recipe-metric {
  margin: 0 0 1.2rem;
  font-size: 2.6rem;
  line-height: 1.1;
  letter-spacing: -0.06em;
  font-weight: 600;
}
.kind-recipe-metric span {
  margin-left: 0.6rem;
  font-size: 0.75rem;
  font-weight: 400;
  letter-spacing: 0;
  color: #687367;
}
.kind-recipe-plot {
  height: 260px;
  width: 100%;
  min-width: 0;
  margin-top: 0.8rem;
}
.kind-recipe-values {
  margin-top: 1.4rem;
  border-top: 1px solid var(--kind-recipe-grid);
  padding-top: 1rem;
  font-size: 0.8rem;
}
.kind-recipe-values summary {
  cursor: pointer;
  width: fit-content;
}
.kind-recipe-table-scroll {
  overflow-x: auto;
}
.kind-recipe-values table {
  border-collapse: collapse;
  width: 100%;
  margin-top: 1rem;
}
.kind-recipe-values caption {
  text-align: left;
  padding-bottom: 0.75rem;
}
.kind-recipe-values th,
.kind-recipe-values td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid var(--kind-recipe-grid);
}
.kind-dashboard {
  padding: clamp(1rem, 4vw, 3.5rem);
  background: #f3f4ed;
  border-radius: 1.5rem;
}
.kind-dashboard-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-bottom: 2rem;
}
.kind-dashboard-header h1 {
  margin: 0;
  max-width: 18ch;
  font-size: clamp(2rem, 4vw, 3.8rem);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.055em;
}
.kind-dashboard-header p:last-child {
  color: #667568;
}
.kind-dashboard-filter {
  display: grid;
  gap: 0.5rem;
  font-size: 0.75rem;
}
.kind-dashboard-filter select {
  border: 1px solid #c8d0c3;
  background: #fffef9;
  color: inherit;
  font: inherit;
  padding: 0.7rem 1rem;
  border-radius: 0.6rem;
}
.kind-dashboard-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.25rem;
}
.kind-dashboard-grid > :first-child {
  grid-column: 1 / -1;
}
.kind-recipe :focus-visible,
.kind-dashboard :focus-visible {
  outline: 2px solid #396b57;
  outline-offset: 4px;
}
@media (max-width: 640px) {
  .kind-dashboard-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .kind-recipe-plot {
    height: 220px;
  }
}

"use client";

import * as Chart from "@kind-ui/charts";
import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import "@kind-ui/charts/styles.css";
import "./kind-chart.css";

export type LineChartDatum = { period: string; current: number; previous: number };
export const lineChartData: LineChartDatum[] = [
  { period: "Jan", current: 38, previous: 24 },
  { period: "Feb", current: 52, previous: 33 },
  { period: "Mar", current: 45, previous: 30 },
  { period: "Apr", current: 68, previous: 47 },
  { period: "May", current: 61, previous: 42 },
  { period: "Jun", current: 84, previous: 59 },
];
const config = {
  current: { label: "This year", color: "var(--kind-recipe-1)" },
  previous: { label: "Last year", color: "var(--kind-recipe-2)" },
} satisfies Chart.SeriesConfig;

/** Editable presentation; chart inspection, visibility and motion come from Kind UI. */
export function KindLineChart({ data = lineChartData }: { data?: LineChartDatum[] }) {
  const [visibleSeries, setVisibleSeries] = useState<string[]>(Object.keys(config));
  return (
    <Card className="kind-recipe kind-recipe-line">
      <CardHeader>
        <p className="kind-recipe-eyebrow">THE BIG PICTURE</p>
        <CardTitle>Revenue momentum</CardTitle>
        <CardDescription>A clear view of the rhythm behind your revenue.</CardDescription>
      </CardHeader>
      <CardContent>
        <p className="kind-recipe-metric">
          {data.reduce((sum, row) => sum + row.current, 0).toLocaleString()}
          <span> thousand USD · this year</span>
        </p>
        <Chart.Root
          config={config}
          visibleSeries={visibleSeries}
          onVisibleSeriesChange={setVisibleSeries}
        >
          <Chart.Legend aria-label="Choose visible revenue momentum series" />
          <div className="kind-recipe-plot">
            <Chart.ResponsiveContainer width="100%" height="100%">
              <Chart.LineChart
                data={data}
                animate
                accessibilityLayer
                aria-label="Revenue momentum by month"
                margin={{ top: 16, right: 12, bottom: 0, left: 0 }}
              >
                <Chart.CartesianGrid vertical={false} stroke="var(--kind-recipe-grid)" />
                <Chart.XAxis
                  dataKey="period"
                  tickLine={false}
                  axisLine={false}
                  tickMargin={12}
                  minTickGap={16}
                />
                <Chart.YAxis tickLine={false} axisLine={false} width={36} />
                <Chart.LineSeries dataKey="current" strokeWidth={3} dot={false} />
                <Chart.LineSeries dataKey="previous" strokeWidth={3} dot={false} />
                <Chart.Tooltip />
              </Chart.LineChart>
            </Chart.ResponsiveContainer>
          </div>
        </Chart.Root>
        <details className="kind-recipe-values">
          <summary>View chart data</summary>
          <div className="kind-recipe-table-scroll">
            <table>
              <caption>Revenue momentum (thousand USD)</caption>
              <thead>
                <tr>
                  <th scope="col">Month</th>
                  <th scope="col">This year</th>
                  <th scope="col">Last year</th>
                </tr>
              </thead>
              <tbody>
                {data.map((row) => (
                  <tr key={row.period}>
                    <th scope="row">{row.period}</th>
                    <td>{row.current.toLocaleString()}</td>
                    <td>{row.previous.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      </CardContent>
    </Card>
  );
}

